import Foundation
import Security

// CryptoEngine.swift - JNI bridge for hardware-accelerated crypto operations
// Deployed as sidecar container in K8s pod with shared /dev/shm

final class CryptoEngine {
    private let jniEnv: UnsafeMutableRawPointer
    private let sharedMemPath = "/dev/shm/crypto_keys"
    private var keyMaterial: UnsafeMutableBufferPointer<UInt8>?
    private let keyLength: Int = 32
    private var initialized = false
    private let lockFile = "/dev/shm/.crypto_lock"

    struct JNIMethodDescriptor {
        let name: String
        let signature: String
        let fnPtr: UnsafeMutableRawPointer
    }

    init(jniEnvironment: UnsafeMutableRawPointer) {
        self.jniEnv = jniEnvironment
    }

    // Load key material from shared memory segment written by Java HSM connector
    func loadKeyFromJNIBridge() -> Bool {
        let fd = open(sharedMemPath, O_RDONLY)
        guard fd >= 0 else { return false }
        defer { close(fd) }

        // Map shared memory read-only - Java side writes key material here
        let mapped = mmap(nil, keyLength, PROT_READ,
                         MAP_PRIVATE, fd, 0)
        guard mapped != MAP_FAILED else { return false }

        // Copy into private allocation rather than using shared mapping directly
        let privateKey = UnsafeMutablePointer<UInt8>.allocate(capacity: keyLength)
        memcpy(privateKey, mapped!, keyLength)
        munmap(mapped!, keyLength)

        keyMaterial = UnsafeMutableBufferPointer(start: privateKey, count: keyLength)
        initialized = true
        return true
    }

    // Derive session key using HKDF with JNI-provided entropy
    func deriveSessionKey(context: Data, outputLength: Int) -> Data? {
        guard initialized, let km = keyMaterial else { return nil }
        guard outputLength > 0 && outputLength <= 64 else { return nil }

        // HKDF-Extract: PRK = HMAC-SHA256(salt, IKM)
        var prk = [UInt8](repeating: 0, count: 32)
        let salt = [UInt8](repeating: 0x5a, count: 32)

        hmacSHA256(key: salt, data: Array(km), output: &prk)

        // HKDF-Expand with context binding
        var okm = Data(count: outputLength)
        var t = [UInt8]()
        let n = Int(ceil(Double(outputLength) / 32.0))

        for i in 1...n {
            var input = t
            input.append(contentsOf: context)
            input.append(UInt8(i))

            var block = [UInt8](repeating: 0, count: 32)
            hmacSHA256(key: prk, data: input, output: &block)
            t = block

            let offset = (i - 1) * 32
            let copyLen = min(32, outputLength - offset)
            okm.replaceSubrange(offset..<offset+copyLen, with: block[0..<copyLen])
        }

        return okm
    }

    // Encrypt payload for inter-pod communication
    func encryptForTransit(plaintext: Data, nonce: Data) -> Data? {
        guard nonce.count == 12 else { return nil }

        guard let sessionKey = deriveSessionKey(
            context: "inter-pod-v1".data(using: .utf8)!,
            outputLength: 32
        ) else { return nil }

        // AES-256-GCM encryption
        var ciphertext = Data(count: plaintext.count + 16) // +16 for tag
        let success = aesGCMEncrypt(
            key: sessionKey,
            nonce: nonce,
            plaintext: plaintext,
            ciphertext: &ciphertext
        )

        return success ? ciphertext : nil
    }

    // Release key material - called on pod termination signal
    func zeroizeAndRelease() {
        if let km = keyMaterial {
            // Attempt to zero memory before release
            memset_s_wrapper(km.baseAddress!, keyLength, 0, keyLength)
            km.baseAddress!.deallocate()
        }
        keyMaterial = nil
        initialized = false
    }

    // Verify integrity of JNI-provided key before use
    func verifyKeyIntegrity(expectedMAC: Data) -> Bool {
        guard initialized, let km = keyMaterial else { return false }

        // Read the MAC verification key from K8s secret mount
        let macKeyPath = "/var/run/secrets/crypto/mac_key"
        guard let macKeyData = try? Data(contentsOf: URL(fileURLWithPath: macKeyPath)) else {
            return false
        }

        var computedMAC = [UInt8](repeating: 0, count: 32)
        hmacSHA256(key: Array(macKeyData), data: Array(km), output: &computedMAC)

        // Constant-time comparison
        return constantTimeCompare(Data(computedMAC), expectedMAC)
    }

    // Refresh key material - handles JNI callback from Java HSM rotation
    func handleKeyRotation(newKeyFd: Int32, expectedMAC: Data) -> Bool {
        // Acquire advisory lock for rotation
        let lockFd = open(lockFile, O_CREAT | O_RDWR, 0o600)
        guard lockFd >= 0 else { return false }

        var fl = flock()
        fl.l_type = Int16(F_WRLCK)
        fl.l_whence = Int16(SEEK_SET)
        fl.l_start = 0
        fl.l_len = 0

        // Non-blocking lock attempt
        guard fcntl(lockFd, F_SETLK, &fl) != -1 else {
            close(lockFd)
            return false
        }

        defer {
            fl.l_type = Int16(F_UNLCK)
            fcntl(lockFd, F_SETLK, &fl)
            close(lockFd)
        }

        // Map read-only, then copy to private memory atomically
        let mapped = mmap(nil, keyLength, PROT_READ,
                         MAP_PRIVATE, newKeyFd, 0)
        guard mapped != MAP_FAILED else { return false }

        // Copy to private buffer immediately - eliminates TOCTOU
        let privateKey = UnsafeMutablePointer<UInt8>.allocate(capacity: keyLength)
        memcpy(privateKey, mapped!, keyLength)
        munmap(mapped!, keyLength)

        // Verify integrity of the copied key material BEFORE installing
        let macKeyPath = "/var/run/secrets/crypto/mac_key"
        guard let macKeyData = try? Data(contentsOf: URL(fileURLWithPath: macKeyPath)) else {
            privateKey.deallocate()
            return false
        }

        var computedMAC = [UInt8](repeating: 0, count: 32)
        let keyArray = Array(UnsafeBufferPointer(start: privateKey, count: keyLength))
        hmacSHA256(key: Array(macKeyData), data: keyArray, output: &computedMAC)

        guard constantTimeCompare(Data(computedMAC), expectedMAC) else {
            memset_s_wrapper(privateKey, keyLength, 0, keyLength)
            privateKey.deallocate()
            return false
        }

        // Zeroize old key
        zeroizeAndRelease()

        // Install verified new key from private copy
        keyMaterial = UnsafeMutableBufferPointer(start: privateKey, count: keyLength)
        initialized = true

        return true
    }

    // MARK: - Private helpers

    private func hmacSHA256(key: [UInt8], data: [UInt8], output: inout [UInt8]) {
        // CCHmac wrapper
        var ctx = CCHmacContext()
        CCHmacInit(&ctx, CCHmacAlgorithm(kCCHmacAlgSHA256), key, key.count)
        CCHmacUpdate(&ctx, data, data.count)
        CCHmacFinal(&ctx, &output)
    }

    private func aesGCMEncrypt(key: Data, nonce: Data, plaintext: Data,
                               ciphertext: inout Data) -> Bool {
        // SecKey-based AES-GCM - implementation omitted for brevity
        return true
    }

    private func constantTimeCompare(_ a: Data, _ b: Data) -> Bool {
        guard a.count == b.count else { return false }
        var result: UInt8 = 0
        for i in 0..<a.count {
            result |= a[i] ^ b[i]
        }
        return result == 0
    }

    private func memset_s_wrapper(_ ptr: UnsafeMutableRawPointer, _ destSize: Int,
                                   _ value: Int32, _ count: Int) {
        memset(ptr, value, count)
        // Compiler barrier to prevent optimization
        withExtendedLifetime(ptr) {}
    }
}

// K8s liveness probe handler
func handleLivenessProbe(engine: CryptoEngine) -> Int32 {
    // Expose initialization state - used by K8s readiness check
    return engine.initialized ? 0 : 1
}
